def build():
 sources={s['id']:s for s in json.loads((D/'Source-Ledger.json').read_text())};facts={f['id']:f for f in json.loads((D/'Facts.json').read_text())};basis=json.loads((ROOT/'cios/applications/flora/visual_v2_assets/economy.json').read_text());out=[]
 for district in sorted(basis['districts'],key=lambda x:x['sic']):
  sic=district['sic'];sid,segments,actors,chain,forces,question,roles,counter,next_task=ROWS[sic];s=sources[sid]
  w=facts['SIC-'+sic+'-WEIGHT24'];g=facts['SIC-'+sic+'-YOY26'];specific=facts.get(sid+'-F1')or facts['UK-RESILIENCE-SEP']
  actor_supported=sic in 'CEFGIJNS';index_only=s['acquisition']=='official_index_only'
  statuses={'identity':'source-backed candidate','economic_size_and_growth':'source-backed candidate','segments':'partial; taxonomy plus bounded interpretation','named_enterprise_roles':'partial source-backed examples'if actor_supported else'unknown/not acquired; regulator/context actor is not an enterprise comparison','customer_supplier_relationships':'partial company-reported relationships'if sic in 'GJ'else'unknown/not acquired; functional mechanism only','PESTLE':'partial; shared macro + sector context, exact applicability open','five_forces':'bounded interpretation; current segment concentration/returns incomplete','value_chain':'bounded interpretation; no complete monetary value-flow proof','competitive_positioning':'partial audit-count evidence'if sic=='M'else'unknown/not acquired on matched current bases','relational_SWOT':'bounded interpretation; no unsupported internal weakness','strategic_decisions':'no enterprise agenda: scope inappropriate'if not question else'candidate question; open choice and buyer need unknown','source_rights_dates':'partial; original bytes/independent acceptance open'}
  from sector_analysis import ANALYSIS
  anchor,transmission,unknown_factors=ANALYSIS[sic]
  pestle={factor:'Not acquired for this sector: '+task for factor,task in unknown_factors.items()}
  pestle['Economic']=f'Official section output {g["value"]:+.1f}% September yoy; 2024 GVA share {w["value"]/10:.1f}%. '+anchor
  pestle.update(transmission)
  swot={'strength_context':counter,'weakness':'No sector-wide internal weakness established; '+next_task,'external_opportunity_hypothesis':question or 'None admitted for enterprise sales.','threat_to_test':forces[3]+' '+forces[4]}
  row={'sic':sic,'panorama_id':district['id'],'label':district['label'],'scope':segments,'source_refs':['ONS-SIC07','ONS-GDP-SEP26',sid],'fact_refs':[w['id'],g['id'],specific['id']],'actors':actors,'pestle':pestle,'relational_swot':swot,'five_forces':dict(zip(['rivalry','new_entrants','substitutes','supplier_power','buyer_power'],forces)),'value_chain':chain,'strategic_questions':[question]if question else[],'decision_role_hypotheses':roles,'counter_evidence_and_limits':counter,'next_research':next_task,'coverage':statuses,'foundational_standard':'PARTIAL — not all substantive gates met','canonical_acceptance':False,'pipeline_handoff':False}
  out.append(row)
  proof='**Original source candidate:** '+specific['statement']+' ['+sid+']('+s['url']+'). Period: '+s['reporting_period']+'. '+('**Index-only, not verified original.**'if index_only else'')
  text=f'# {district["label"]} — UK SIC 2007 {sic}\n\n**Controlled foundational tranche; partial, not an accepted Industry Twin.** As of 14 November 2026.\n\n## Boundary and measured economics\n\n{segments}\n\nOfficial 2024 GVA weight: **{w["value"]}/1000 ({w["value"]/10:.1f}%)**. September 2026 real GVA volume: **{g["value"]:+.1f}% versus September 2025**. These are different bases/periods, not current sales, sector profit or addressable budget. [ONS GVA3 appendix, page index 29](https://www.ons.gov.uk/economy/grossdomesticproductgdp/bulletins/gdpmonthlyestimateuk/september2026/pdf). Rounded shares are not normalised.\n\n{proof}\n\n## Actors and value creation\n\n{actors}\n\n**Interpretation:** {chain} Actual named contracts, spend concentration and profit pools require their own evidence.\n\n## Forces of Change — applicability to validate\n\n'+''.join('- **'+k+':** '+v+'\n'for k,v in pestle.items())+'\n## Competitive economics — interpreted mechanisms, no scores\n\n'+''.join('- **'+k.replace('_',' ').title()+':** '+v+'\n'for k,v in row['five_forces'].items())+'\n## Strategic synthesis and a useful next question\n\n**Relational SWOT — interpretation, not entity diagnoses:** '+ ' '.join(k.replace('_',' ').title()+': '+v for k,v in swot.items())+'\n\n'+('**Question:** '+question+'\n\n**Role categories, unconfirmed:** '+roles+'. Existing owners/incumbents/internal responses may already settle it; no open procurement, budget or customer need is established.\n\n'if question else'**No enterprise sales agenda admitted.** This scope does not justify an enterprise opportunity or household targeting.\n\n')+'**Next evidence action:** '+next_task+'\n\n## Dimension coverage\n\n'+''.join('- '+k.replace('_',' ')+': **'+v+'**.\n'for k,v in statuses.items())+'\nNo completion percentage. No automatic Material Pressure, Observation acceptance or Pipeline write.\n'
  (D/'sectors'/('SIC-'+sic+'.md')).write_text('\n'.join(line.rstrip()for line in text.splitlines())+'\n')
 (D/'Sector-Research.json').write_text(json.dumps(out,indent=2)+'\n')
 lines=['# Twenty-sector coverage — substantive dimensions, not a percentage','','All 20 exact displayed sections assessed; **all remain partial** against the predeclared foundational standard. Method coverage is not completed research. Size/growth has one consistent ONS vintage; enterprise, relationship and competitive depth vary.','','| SIC / sector | Current context proof | Named enterprise depth | Comparative economics | Most material next task |','|---|---|---|---|---|']
 for row in out:
  lines.append('| ['+row['sic']+' · '+row['label']+'](sectors/SIC-'+row['sic']+'.md) | '+row['source_refs'][-1]+' | '+row['coverage']['named_enterprise_roles']+' | '+row['coverage']['competitive_positioning']+' | '+row['next_research']+' |')
 (D/'Twenty-Sector-Coverage.md').write_text('\n'.join(lines)+'\n')
 print('20 authored, inspectable sector dossiers; all substantive deficiencies remain visible.')
if __name__=='__main__':build()
